<script setup lang="ts">
import DirectorPropEditor from './DirectorPropEditor.vue';
import { computed, shallowRef, watch } from 'vue';
import { cameraAt, directorActions, directorKinds, directorEases, objectAt, type ActionClip, type CameraFollow, type DirectorAction, type DirectorJoint, type DirectorPose, type CameraKey, type DirectorDocument, type DirectorObject, type ObjectKey } from '@/utils/dramaDirector';
import DirectorVectorFields from './DirectorVectorFields.vue';
import DirectorActionEditor from './DirectorActionEditor.vue';
import DirectorPoseEditor from './DirectorPoseEditor.vue';
const props = defineProps<{ document: DirectorDocument; selected: string; frame: number; joint: DirectorJoint; selectedClip: string; canPaste: boolean; poseMode: boolean; clipSelection: number }>();
const emit = defineEmits<{ object: [patch: Partial<DirectorObject>]; objectKey: [patch: Partial<ObjectKey>]; cameraKey: [patch: Partial<CameraKey>]; addKey: []; deleteKey: []; duplicate: []; remove: []; seek: [frame: number]; joint: [joint: DirectorJoint]; pose: [pose: DirectorPose]; copyPose: []; pastePose: []; mirrorPose: []; addClip: [action: DirectorAction]; selectClip: [id:string]; patchClip: [id:string, patch:Partial<ActionClip>]; removeClip: [id:string]; duplicateClip: [id:string]; retime: [to:number,copy:boolean]; follow: [id:string]; patchFollow: [patch:Partial<CameraFollow>] }>();
const object = computed(() => props.document.objects.find(o => o.id === props.selected));
const pose = computed(() => object.value ? objectAt(object.value, props.frame) : undefined);
const camera = computed(() => cameraAt(props.document, props.frame));
const keys = computed(() => props.selected === 'camera' ? props.document.camera.keys : object.value?.keys || []);
const hasKey = computed(() => keys.value.some(k => k.frame === props.frame));
const tab = shallowRef<'movement'|'action'|'pose'>('movement'), destination = shallowRef(24);
const lookTargets = computed(()=>props.document.objects.filter(o=>o.id!==props.selected));
watch(()=>[props.selectedClip,props.clipSelection],()=>{if(props.selectedClip)tab.value='action';});
watch(()=>props.poseMode,value=>{if(value)tab.value='pose';});
watch(()=>props.joint,()=>{if(props.poseMode)tab.value='pose';});
watch(()=>props.frame,()=>{destination.value=Math.min(props.frame+24,props.document.duration*24-1);});
function number(event: Event) { return Number((event.target as HTMLInputElement).value); }
function aim(event: Event) { const target = props.document.objects.find(o => o.id === (event.target as HTMLSelectElement).value); if (target) { const key = objectAt(target, props.frame); emit('cameraKey', { target: [key.position[0], key.position[1] + (target.kind === 'actor' ? 1.3 : .5), key.position[2]] }); } }
</script>
<template>
  <aside class="director-inspector" aria-label="导演对象属性">
    <header><small>PROPERTIES</small><h2>{{selected==='camera' ? '摄影机' : object?.name || '选择场景对象'}}</h2><span>{{selected==='camera' ? '机位 · 构图 · 运镜' : object ? directorKinds[object.kind] : '点击白模或左侧场景列表'}}</span></header>
    <div v-if="object || selected==='camera'" class="inspector-scroll">
      <div class="key-status"><i :class="{active:hasKey}"/><span>当前 {{(frame/24).toFixed(2)}}s · {{hasKey ? '已记录关键帧' : '插值姿态'}}</span></div>
      <div v-if="object?.kind==='actor'" class="inspector-tabs"><button v-for="(label,key) in {movement:'走位',action:'动作编排',pose:'关节姿态'}" :key="key" :class="{active:tab===key}" @click="tab=key">{{label}}</button></div>
      <template v-if="object && pose">
        <DirectorActionEditor v-if="object.kind==='actor' && tab==='action'" :object="object" :frame="frame" :end="document.duration*24-1" :selected-clip="selectedClip" @add="emit('addClip',$event)" @select="emit('selectClip',$event)" @patch="(id,patch)=>emit('patchClip',id,patch)" @remove="emit('removeClip',$event)" @duplicate="emit('duplicateClip',$event)"/>
        <DirectorPoseEditor v-else-if="object.kind==='actor' && tab==='pose'" :pose="pose.pose || {}" :joint="joint" :locked="object.locked" :can-paste="canPaste" @joint="emit('joint',$event)" @patch="emit('pose',$event)" @copy="emit('copyPose')" @paste="emit('pastePose')" @mirror="emit('mirrorPose')"/>
        <template v-else>
        <label class="field"><span>对象名称</span><input :value="object.name" aria-label="白模对象名称" maxlength="100" @change="emit('object',{name:($event.target as HTMLInputElement).value || object.name})"></label>
        <div class="field"><span>位置（米）</span><DirectorVectorFields :value="pose.position" label="对象位置" :disabled="object.locked" @change="emit('objectKey',{position:$event})"/></div>
        <label class="field"><span>朝向（度）</span><input type="number" :value="Number(pose.yaw.toFixed(2))" min="-360" max="360" step="5" aria-label="对象朝向" :disabled="object.locked" @change="emit('objectKey',{yaw:number($event)})"></label>
        <div class="field"><span>尺寸倍率（人物默认约 1.8 米）</span><DirectorVectorFields :value="object.scale" label="对象尺寸" :disabled="object.locked" :min=".1" :max="20" @change="emit('object',{scale:$event})"/></div>
        <DirectorPropEditor :object="object" :objects="document.objects" :frame="frame" :end="document.duration*24-1" @patch="emit('object',$event)"/>
        <label v-if="object.kind==='actor'" class="field"><span>基础动作（未编排片段时）</span><select :value="pose.action" aria-label="白模动作" :disabled="object.locked" @change="emit('objectKey',{action:($event.target as HTMLSelectElement).value as ObjectKey['action']})"><option v-for="(label,value) in directorActions" :key="value" :value="value">{{label}}</option></select></label>
        <label v-if="object.kind==='actor'" class="toggle-field"><input type="checkbox" :checked="object.autoFace" :disabled="object.locked" aria-label="沿路线自动朝向" @change="emit('object',{autoFace:($event.target as HTMLInputElement).checked})">沿路线自动朝向</label>
        <label v-if="object.kind==='actor'" class="toggle-field"><input type="checkbox" :checked="object.grounded" :disabled="object.locked" aria-label="自动脚底贴地" @change="emit('object',{grounded:($event.target as HTMLInputElement).checked})">自动脚底贴地</label>
        <label v-if="object.kind==='actor'" class="toggle-field"><input type="checkbox" :checked="object.quaternionPose" :disabled="object.locked" aria-label="关节球面插值" @change="emit('object',{quaternionPose:($event.target as HTMLInputElement).checked})">关节球面插值（适合转体）</label>
        <label v-if="object.kind==='actor'" class="field"><span>头部持续注视</span><select :value="object.lookAtId || ''" :disabled="object.locked" aria-label="头部注视对象" @change="emit('object',{lookAtId:($event.target as HTMLSelectElement).value || undefined})"><option value="">自由姿态</option><option v-for="o in lookTargets" :key="o.id" :value="o.id">{{o.name}}</option></select></label>
        <label class="field"><span>到下一关键帧的移动</span><select :value="pose.ease || 'linear'" aria-label="人物插值方式" :disabled="object.locked" @change="emit('objectKey',{ease:($event.target as HTMLSelectElement).value as ObjectKey['ease']})"><option v-for="(label,key) in directorEases" :key="key" :value="key">{{label}}</option></select></label>
        <label class="color-field"><span>白模颜色</span><input type="color" :value="object.color" aria-label="白模颜色" @change="emit('object',{color:($event.target as HTMLInputElement).value})"></label>
        <div class="object-actions"><button @click="emit('duplicate')">创建副本</button><button class="danger" :disabled="object.locked" @click="emit('remove')">删除对象</button></div>
        <p v-if="object.locked" class="hint">此对象已锁定。先在场景列表中解锁，再调整坐标、尺寸或动作。</p>
        </template>
      </template>
      <template v-else>
        <div class="field"><span>机位位置（米）</span><DirectorVectorFields :value="camera.position" label="机位位置" @change="emit('cameraKey',{position:$event})"/></div>
        <div class="field"><span>拍摄目标（米）</span><DirectorVectorFields :value="camera.target" label="拍摄目标" @change="emit('cameraKey',{target:$event})"/></div>
        <label class="field"><span>瞄准场景对象（当前时刻）</span><select aria-label="瞄准场景对象" :value="''" @change="aim"><option value="">选择人物或道具</option><option v-for="o in document.objects" :key="o.id" :value="o.id">{{o.name}}</option></select></label>
        <label class="field"><span>视角 FOV（度）</span><input type="number" :value="Number(camera.fov.toFixed(2))" min="15" max="100" aria-label="机位视角" @change="emit('cameraKey',{fov:number($event)})"></label>
        <label class="field"><span>画面倾斜（度）</span><input type="number" :value="Number(camera.roll.toFixed(2))" min="-180" max="180" aria-label="机位画面倾斜" @change="emit('cameraKey',{roll:number($event)})"></label>
        <label class="field"><span>到下一机位的移动</span><select :value="camera.ease || 'linear'" aria-label="机位插值方式" @change="emit('cameraKey',{ease:($event.target as HTMLSelectElement).value as CameraKey['ease']})"><option v-for="(label,key) in directorEases" :key="key" :value="key">{{label}}</option></select></label>
        <label class="field"><span>持续跟随目标</span><select :value="document.camera.follow?.objectId || ''" aria-label="摄影机持续跟随目标" @change="emit('follow',($event.target as HTMLSelectElement).value)"><option value="">不跟随 · 手动设置目标</option><option v-for="o in document.objects" :key="o.id" :value="o.id">{{o.name}}</option></select></label>
        <template v-if="document.camera.follow"><label class="field"><span>跟随方式</span><select :value="document.camera.follow.mode" aria-label="摄影机跟随方式" @change="emit('patchFollow',{mode:($event.target as HTMLSelectElement).value as CameraFollow['mode']})"><option value="aim">只跟随视线 · 机位仍按关键帧移动</option><option value="follow">机位与视线一起跟随</option></select></label><label class="field"><span>注视高度（米）</span><input type="number" min="0" max="3" step="0.1" :value="document.camera.follow.height" aria-label="摄影机跟随注视高度" @change="emit('patchFollow',{height:number($event)})"></label><div v-if="document.camera.follow.mode==='follow'" class="field"><span>相对人物的机位距离（米）</span><DirectorVectorFields :value="document.camera.follow.offset" label="跟随机位偏移" @change="emit('patchFollow',{offset:$event})"/></div></template>
        <p class="hint">「只跟随视线」保留推拉、绕拍路线；「机位与视线一起跟随」使用固定的世界坐标偏移。关闭跟随后可继续手动编辑目标。</p>
      </template>
      <section class="keys"><div><strong>关键帧</strong><button :disabled="object?.locked" @click="emit('addKey')">＋ 记录当前</button></div><div class="key-list"><button v-for="k in keys" :key="k.frame" :class="{selected:k.frame===frame}" @click="emit('seek',k.frame)"><i/>{{(k.frame/24).toFixed(2)}}s<small>{{k.frame}}f</small></button></div><button class="delete-key" :disabled="!hasKey || frame===0 || object?.locked" @click="emit('deleteKey')">删除当前关键帧</button><div class="key-retime"><label>目标帧<input v-model.number="destination" type="number" min="0" :max="document.duration*24-1" aria-label="关键帧目标时间"></label><button :disabled="!hasKey || object?.locked" @click="emit('retime',destination,true)">复制到此帧</button><button :disabled="!hasKey || frame===0 || object?.locked" @click="emit('retime',destination,false)">移动到此帧</button></div><p class="hint">时间轴拖动菱形可移动关键帧（第 0 帧保留）。编辑坐标或关节会记录当前帧；动作片段有独立起止时间。</p></section>
    </div>
    <div v-else class="inspector-empty">添加人物、摆放道具，选中对象后在这里设置位置和动作。</div>
  </aside>
</template>
<style scoped>
.director-inspector{display:flex;flex-direction:column;background:white;border-left:1px solid #dfe6ef;min-height:0;overflow:hidden}.director-inspector header{padding:22px 20px 18px;border-bottom:1px solid #e8edf4}.director-inspector header small{font-size:9px;letter-spacing:1.7px;color:#91a2b9}.director-inspector h2{font-size:16px;margin:9px 0;color:#233751}.director-inspector header>span{font-size:10px;color:#8190a7}.inspector-scroll{padding:18px 20px;overflow:auto;flex:1;min-height:0}.key-status{display:flex;align-items:center;gap:7px;font-size:10px;color:#7790af;margin-bottom:20px}.key-status i,.key-list i{width:6px;height:6px;background:#cbd6e5;transform:rotate(45deg);display:inline-block}.key-status .active{background:#3c82df}.field{display:grid;gap:9px;margin-bottom:18px;font-size:11px;color:#5b6f89}.field>input,.field select{box-sizing:border-box;width:100%;height:33px;border:1px solid #dce4ee;border-radius:5px;padding:0 10px;font:11px inherit;color:#38506f;background:#f8fafc;outline:none}.field>input:focus,.field select:focus{border-color:#4c8ade}.color-field{display:flex;justify-content:space-between;align-items:center;font-size:11px;color:#5b6f89;margin:18px 0}.color-field input{width:34px;height:26px;border:0;background:none;padding:0;cursor:pointer}.object-actions{display:flex;gap:8px}.object-actions button,.keys button{background:#f8fafc;color:#53708f;border:1px solid #dce4ee;border-radius:4px;padding:7px 9px;font:10px inherit;cursor:pointer}.object-actions button{flex:1}.object-actions .danger{color:#ad6567}.keys{margin-top:24px;padding-top:20px;border-top:1px solid #e8edf4}.keys>div:first-child{display:flex;justify-content:space-between;align-items:center}.keys strong{font-size:11px;color:#48617f}.key-list{display:grid;gap:6px;margin:12px 0}.key-list button{display:flex;align-items:center;gap:8px;text-align:left}.key-list small{margin-left:auto;color:#9aa7b9}.key-list .selected{color:#2f75d3;background:#edf5ff;border-color:#9bbce6}.key-list .selected i{background:#3c82df}.delete-key{width:100%}.keys button:disabled,.object-actions button:disabled{opacity:.4;cursor:default}.hint{font-size:10px;color:#96a3b5;line-height:1.8;margin:13px 0 0}.inspector-empty{padding:26px 20px;font-size:11px;line-height:1.9;color:#8b9ab0}
.inspector-tabs{display:flex;gap:3px;padding:3px;background:#f0f4fa;border-radius:5px;margin-bottom:22px}.inspector-tabs button{flex:1;padding:8px 0;border:0;border-radius:3px;background:none;color:#7b8fa9;font:10px inherit;cursor:pointer}.inspector-tabs .active{background:white;color:#3278d1;box-shadow:0 1px 4px #34507416}.toggle-field{display:flex;align-items:center;gap:7px;font-size:11px;color:#5f7898;margin:0 0 17px}.toggle-field input{accent-color:#3d80d8}.key-retime{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-top:12px}.key-retime label{grid-column:1/3;display:flex;align-items:center;justify-content:space-between;font-size:10px;color:#8194ae;padding:5px 0}.key-retime input{width:72px;border:1px solid #dce5f1;border-radius:3px;padding:5px;color:#587699;font:11px inherit}
</style>
